1) Prime Number
i)Finding whether the given number is prime or not:
let num = 7;
let isPrime = true;

for (let i = 2; i < num; i++) {
    if (num % i === 0) {
        isPrime = false;
        break;
    }
}

if (num > 1 && isPrime) {
    console.log("Prime");
} else {
    console.log("Not Prime");
}

Output:
Prime

ii)Printing all the prime numbers within the 2-50:
for (let num = 2; num <= 50; num++) {

    let isPrime = true;

    for (let i = 2; i < num; i++) {
        if (num % i === 0) {
            isPrime = false;
            break;
        }
    }

    if (isPrime) {
        console.log(num);
    }
}

Output:
2
3
5
7
